export function candidateFixture(){mkdirSync(resolve('.test-data'),{recursive:true});const root=mkdtempSync(resolve('.test-data/s08-candidate-')),app=join(root,'resources/app');mkdirSync(join(app,'dist-electron'),{recursive:true});mkdirSync(join(app,'dist'),{recursive:true});const files=['HTC.exe','resources/app/dist-electron/main.cjs','resources/app/dist-electron/preload.cjs','resources/app/dist/index.html','resources/app/package.json'].map((path,i)=>{const bytes=Buffer.from(i===4?JSON.stringify({main:'dist-electron/main.cjs'}):'synthetic candidate '+i);writeFileSync(join(root,path),bytes);return{path,size:bytes.length,sha256:sha(bytes)};}),manifest={schema:'htc-package/v1',source:{commit:'a'.repeat(40),sourceDigest:'b'.repeat(64)},build:{schema:'htc-build/v1',sourceCommit:'a'.repeat(40),sourceDigest:'b'.repeat(64),files:files.filter(f=>f.path.startsWith('resources/app/dist')).map(f=>({...f,path:f.path.slice('resources/app/'.length)}))},files};writeFileSync(join(root,'版本与摘要.json'),JSON.stringify(manifest));return{root,app,exe:join(root,'HTC.exe'),manifest};}
